<?php

declare(strict_types=1);namespace OCA\MaintenanceTracker\Service;
use JsonException;use OCA\MaintenanceTracker\Db\ComponentMapper;use OCA\MaintenanceTracker\Db\Specification;use OCA\MaintenanceTracker\Db\SpecificationMapper;use OCA\MaintenanceTracker\Exception\ValidationException;use OCA\MaintenanceTracker\Model\WorkspaceContext;use OCP\IDBConnection;use OCP\AppFramework\Db\DoesNotExistException;use OCP\AppFramework\Utility\ITimeFactory;
final class SpecificationService{private const SOURCES=['profile','manual','manufacturer','service_manual','service_bulletin','import','other'];public function __construct(private AssetService $assets,private ComponentMapper $components,private SpecificationMapper $mapper,private UuidGenerator $uuidGenerator,private ChangeJournal $journal,private IDBConnection $db,private ITimeFactory $timeFactory){}
 public function list(WorkspaceContext $c,string $assetUuid):array{$asset=$this->assets->find($c,$assetUuid);$components=$this->components->findForAsset($c->workspace()->getId(),$asset->getId());$ids=[];foreach($components as $component)$ids[$component->getId()]=$component->getUuid();return array_map(fn(Specification $s)=>$s->toApi($s->getComponentId()===null?null:($ids[$s->getComponentId()]??null)),$this->mapper->findForAsset($c->workspace()->getId(),$asset->getId()));}
 public function create(WorkspaceContext $c,string $assetUuid,array $in):Specification{$asset=$this->assets->find($c,$assetUuid);$allowed=['uuid','componentUuid','key','label','value','unit','regime','source'];$u=array_diff(array_keys($in),$allowed);if($u!==[])throw new ValidationException('Unknown specification fields: '.implode(', ',$u));foreach(['key','label','value']as$f)if(!array_key_exists($f,$in))throw new ValidationException("{$f} is required");$componentId=null;if(isset($in['componentUuid'])&&$in['componentUuid']!==''){try{$component=$this->components->findByUuid($c->workspace()->getId(),strtolower((string)$in['componentUuid']));}catch(DoesNotExistException){throw new ValidationException('componentUuid was not found');}if($component->getAssetId()!==$asset->getId())throw new ValidationException('componentUuid must belong to the same asset');$componentId=$component->getId();}$key=$this->key($in['key'],'key',160);$label=$this->text($in['label'],'label',255,false);$unit=$this->text($in['unit']??null,'unit',64,false,true);$regime=$in['regime']??null;$regime=$regime===null||$regime===''?null:$this->key($regime,'regime',64);$sourceType=null;$sourceRef=null;if(isset($in['source'])){if(!is_array($in['source']))throw new ValidationException('source must be an object');$sourceType=$this->text($in['source']['type']??null,'source.type',32,false);if(!in_array($sourceType,self::SOURCES,true))throw new ValidationException('Unsupported specification source type');$sourceRef=$this->text($in['source']['reference']??null,'source.reference',2000,true,true);}try{$valueJson=json_encode($in['value'],JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES);}catch(JsonException $e){throw new ValidationException('value must be JSON serializable',0,$e);}if(strlen($valueJson)>20000)throw new ValidationException('value exceeds the specification size limit');$now=$this->timeFactory->getTime();$s=new Specification();$s->setWorkspaceId($c->workspace()->getId());$s->setAssetId($asset->getId());$s->setComponentId($componentId);$s->setUuid(isset($in['uuid'])?(string)$in['uuid']:$this->uuidGenerator->generate());$s->setSpecKey($key);$s->setLabel($label);$s->setValueJson($valueJson);$s->setUnit($unit);$s->setRegimeKey($regime);$s->setSourceType($sourceType);$s->setSourceRef($sourceRef);$s->setRevision(1);$s->setCreatedAt($now);$s->setUpdatedAt($now);$s->setDeletedAt(null);$owns=!$this->db->inTransaction();if($owns)$this->db->beginTransaction();try{$s=$this->mapper->insert($s);$this->journal->record($s->getWorkspaceId(),'specification',$s->getUuid(),'upsert',1,$now);if($owns)$this->db->commit();return $s;}catch(\Throwable $e){if($owns&&$this->db->inTransaction())$this->db->rollBack();throw $e;}}
 private function key(mixed $v,string $f,int $m):string{$s=$this->text($v,$f,$m,false);if(preg_match('/^[a-z0-9][a-z0-9._-]*$/D',$s)!==1)throw new ValidationException("{$f} must be a lowercase semantic key");return $s;}private function text(mixed $v,string $f,int $m,bool $nl,bool $opt=false):?string{if($opt&&($v===null||$v===''))return null;if(!is_string($v))throw new ValidationException("{$f} must be a string");$v=trim($v);if($v===''&&!$opt)throw new ValidationException("{$f} cannot be empty");if(mb_strlen($v)>$m)throw new ValidationException("{$f} exceeds {$m} characters");$p=$nl?'/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u':'/[\x00-\x1F\x7F]/u';if(preg_match($p,$v)===1)throw new ValidationException("{$f} contains unsupported control characters");return $v===''?null:$v;}}
